def transform(grid):
 g=[row[:] for row in grid]; bg=g[0][0]; pts=[(r,c) for r,row in enumerate(g) for c,v in enumerate(row) if v!=bg]
 r0=min(r for r,c in pts); r1=max(r for r,c in pts); c0=min(c for r,c in pts); c1=max(c for r,c in pts)
 for c in range(c0,c1+1):
  if g[r0][c]==bg:g[r0][c]=2
  if g[r1][c]==bg:g[r1][c]=2
 for r in range(r0,r1+1):
  if g[r][c0]==bg:g[r][c0]=2
  if g[r][c1]==bg:g[r][c1]=2
